package com.bank.flink.sql;

import java.math.BigDecimal;

// A changelog row: the way a dynamic table emits changes to a stream.
class ChangelogEvent {
    enum Kind { INSERT, UPDATE_BEFORE, UPDATE_AFTER, DELETE }

    private final Kind kind;
    private final String accountId;
    private final long count;
    private final BigDecimal total;

    ChangelogEvent(Kind kind, String accountId, long count, BigDecimal total) {
        this.kind = kind;
        this.accountId = accountId;
        this.count = count;
        this.total = total;
    }

    @Override
    public String toString() {
        return kind + "(account=" + accountId + ", count=" + count + ", total=" + total + ")";
    }

    Kind getKind() { return kind; }
    String getAccountId() { return accountId; }
}
