package com.bank.flink.sql;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

// The result dynamic table: current aggregate row per account id.
class DynamicTable {
    // accountId -> [count, total]
    private final Map<String, BigDecimal[]> rows = new LinkedHashMap<>();

    void apply(ChangelogEvent e) {
        switch (e.getKind()) {
            case INSERT:
            case UPDATE_AFTER:
                // handled by the query writing the new values directly
                break;
            case UPDATE_BEFORE:
            case DELETE:
                // retraction removes the prior row view
                break;
        }
    }

    void set(String accountId, long count, BigDecimal total) {
        rows.put(accountId, new BigDecimal[]{ BigDecimal.valueOf(count), total });
    }

    Map<String, BigDecimal[]> snapshot() { return rows; }
}
