package com.bank.flink.sql;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Stands in for the compiled plan of:
//   SELECT account_id, COUNT(*), SUM(amount) FROM transactions GROUP BY account_id
// It maintains per-key state and emits the changelog (retract + insert) on update.
class ContinuousAggregateQuery {
    private static final Logger log = Logger.getLogger(ContinuousAggregateQuery.class.getName());

    private final Map<String, long[]> counts = new HashMap<>();      // accountId -> count
    private final Map<String, BigDecimal> totals = new HashMap<>();  // accountId -> total
    private final DynamicTable result = new DynamicTable();

    // Process one input row; returns the changelog events this update emits.
    List<ChangelogEvent> onRow(Row row) {
        List<ChangelogEvent> changelog = new ArrayList<>();
        String acct = row.getAccountId();
        boolean existed = counts.containsKey(acct);

        if (existed) {
            long oldCount = counts.get(acct)[0];
            BigDecimal oldTotal = totals.get(acct);
            // UPDATE: retract the old aggregate row, then emit the new one.
            changelog.add(new ChangelogEvent(ChangelogEvent.Kind.UPDATE_BEFORE, acct, oldCount, oldTotal));
        }

        long newCount = (existed ? counts.get(acct)[0] : 0) + 1;
        BigDecimal newTotal = (existed ? totals.get(acct) : BigDecimal.ZERO).add(row.getAmount());
        counts.put(acct, new long[]{ newCount });
        totals.put(acct, newTotal);
        result.set(acct, newCount, newTotal);

        changelog.add(new ChangelogEvent(
                existed ? ChangelogEvent.Kind.UPDATE_AFTER : ChangelogEvent.Kind.INSERT,
                acct, newCount, newTotal));
        changelog.forEach(e -> log.info(() -> "changelog -> " + e));
        return changelog;
    }

    DynamicTable getResult() { return result; }
}
