package com.bank.flink.sql;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: feed transactions, show the continuous GROUP BY emitting a
// changelog and the result dynamic table updating as events arrive.
public class FlinkSqlDemo {
    private static final Logger log = Logger.getLogger(FlinkSqlDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new SqlLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ContinuousAggregateQuery query = new ContinuousAggregateQuery();

        Row[] stream = {
            new Row("SAV2001", new BigDecimal("1000")),
            new Row("CUR3001", new BigDecimal("500")),
            new Row("SAV2001", new BigDecimal("250")),  // updates SAV2001
            new Row("CUR3001", new BigDecimal("700"))   // updates CUR3001
        };

        for (Row row : stream) {
            log.info(() -> "INPUT row account=" + row.getAccountId() + " amount " + row.getAmount());
            query.onRow(row);
            StringBuilder sb = new StringBuilder("RESULT TABLE: ");
            query.getResult().snapshot().forEach((acct, cv) ->
                    sb.append(acct).append("[count=").append(cv[0]).append(",total=").append(cv[1]).append("] "));
            log.info(sb::toString);
        }
    }
}

// ─── Would be in SqlLogFormatter.java in a real project ───
class SqlLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
